INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('3c7aeb85-1858-467c-975d-a666e9d8ebd0', 'a1a1a1a1-3030-4000-8000-000000000001', 15, 'Dia 15 — Visão', 'Semana 3: Reconstruir', '{"pch": "Escreve a vis\u00e3o\u2026 e torna-a clara. O que n\u00e3o est\u00e1 escrito, n\u00e3o se realiza.", "verse": "Hc 2,2", "lectio": "Leia Hc 2,1-4. A vis\u00e3o tem tempo certo.", "practice": "Escreva sua vis\u00e3o de vida em 1 par\u00e1grafo.", "question": "Qual sua vis\u00e3o para os pr\u00f3ximos 5 anos?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;